look.customCSS:
/* ───── 青瓷×焦茶 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScyMicgaGVpZ2h0PScyMicgdmlld0JveD0nMCAwIDIyIDIyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PGNpcmNsZSBjeD0nMTQnIGN5PScxNCcgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PC9zdmc+") 0 0/22px 22px,#F3EBDA !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：米白底，下面一道焦茶线 */
[data-wk="chathead"]{background:#FBF6EA !important;border-bottom:1.6px solid #4A3A30 !important;box-shadow:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#4A3A30 !important}
[data-wk="headdim"]{color:#A79E92 !important}
[data-wk="chatback"] svg{stroke:#4A3A30 !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{border-radius:10px !important;box-shadow:0 0 0 1.6px #4A3A30 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgMTEgTDEyIDQgTDIwIDExIFYyMCBINFonIGZpbGw9J25vbmUnIHN0cm9rZT0nIzRBM0EzMCcgc3Ryb2tlLXdpZHRoPScxLjYnIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/22px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48L3N2Zz4=") center/22px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆角方块，焦茶细边 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:10px !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 1.6px #4A3A30 !important}

/* 名字：只给我那边一个「Me」 */
[data-wk="name"][data-me="0"]{display:none !important}
[data-wk="name"][data-me="1"]{font-size:0 !important;margin:0 4px 6px !important}
[data-wk="name"][data-me="1"]::after{content:"Me" !important;font-size:12px !important;color:#4A3A30 !important;letter-spacing:.06em !important}

/* 气泡：焦茶描边；我的青瓷、角上一颗星；他的米白、里面「」两个角标、顶上探出一只小猫 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;color:#4A3A30 !important;padding:11px 22px !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#A9D3C3 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTEgMTEgVjEgSDExJyBmaWxsPSdub25lJyBzdHJva2U9JyM0QTNBMzAnIHN0cm9rZS13aWR0aD0nMS42Jy8+PC9zdmc+") 8px 7px/11px 11px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTExIDEgVjExIEgxJyBmaWxsPSdub25lJyBzdHJva2U9JyM0QTNBMzAnIHN0cm9rZS13aWR0aD0nMS42Jy8+PC9zdmc+") right 8px bottom 7px/11px 11px no-repeat,#FBF6EA !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:-10px !important;bottom:-10px !important;left:auto !important;top:auto !important;width:22px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]{margin-top:22px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;right:14px !important;left:auto !important;top:-20.5px !important;width:52px !important;height:21.7px !important;background:url("data:image/svg+xml;base64,") center bottom/contain no-repeat !important;border:none !important;transform:none !important}

/* 时间、已读：浅灰小字 */
[data-wk="time"] > span{background:#FBF6EA !important;color:#4A3A30 !important;border:1.6px solid #4A3A30 !important;border-radius:999px !important;padding:2px 12px !important;font-size:11px !important}
[data-wk="meta"]{color:#A79E92 !important;font-size:10.5px !important}
[data-wk="bubble"][data-kind="typing"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#4A3A30 !important}
[data-wk="narrink"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;color:#4A3A30 !important;padding:3px 10px !important}
[data-wk="sysnotetext"]{color:#A79E92 !important}

/* 底栏：米白底一道焦茶线；输入框圆角描边；发送键是「发送」两个字的青瓷块，角上一颗星 */
[data-wk="composer"]{background:#FBF6EA !important;border-top:1.6px solid #4A3A30 !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#fff !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;color:#4A3A30 !important}
[data-wk="chatinput"]::placeholder{color:#A79E92 !important}
[data-wk="chatplus"],[data-wk="chatreply"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important}
[data-wk="send"]{order:99 !important;position:relative !important;overflow:visible !important;width:64px !important;min-width:64px !important;height:36px !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;background:#A9D3C3 !important;box-shadow:none !important;opacity:1 !important;margin-right:6px !important}
[data-wk="send"]::before{content:"发送" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;font-size:14px !important;letter-spacing:.2em !important;color:#4A3A30 !important}
[data-wk="send"]::after{content:"" !important;position:absolute !important;right:-9px !important;bottom:-9px !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
[data-wk="msg"][data-me="0"] [data-wk="name"]{display:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{margin-right:14px !important}


/* ───── 青瓷焦茶 · 第二批：卡片（形状不动，米白底焦茶描边；小巧思：转账、名片、线下小结的卡角趴一只同款小猫，收下的印是一颗星） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:14px !important;box-shadow:none !important;color:#4A3A30 !important;position:relative !important;overflow:visible !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#4A3A30 !important;border-color:rgba(74,58,48,.25) !important}
[data-wk="transfercard"],[data-wk="namecard"],[data-part="offlog"]{margin-top:20px !important}
[data-wk="transfercard"]::before,[data-wk="namecard"]::before,[data-part="offlog"]::before{content:"" !important;position:absolute !important;right:16px !important;top:-20.5px !important;width:52px !important;height:21.7px !important;background:url("data:image/svg+xml;base64,") center bottom/contain no-repeat !important;z-index:2 !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#4A3A30 !important;font-weight:700 !important}
[data-wk="transferrule"]{border:none !important;height:1.6px !important;background:#4A3A30 !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#F3EBDA !important;border-radius:0 0 12px 12px !important}
[data-wk="transferbtn"]{border-radius:10px !important;border:1.6px solid #4A3A30 !important}
[data-wk="transferbtn"][data-part="take"]{background:#A9D3C3 !important;color:#4A3A30 !important}
[data-wk="transferbtn"][data-part="back"]{background:#FBF6EA !important;color:#4A3A30 !important}
[data-wk="transferseal"]{border:1.6px solid #4A3A30 !important;color:#4A3A30 !important;background:#FBF6EA !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;width:52px !important;height:52px !important;border-radius:0 !important;transform:rotate(-10deg) !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.6 !important}
/* 红包：一个青瓷色小信封——焦茶描边、三角封口压一道折线、封口上贴一颗星；领完变米白、星变空 */
[data-wk="rpcard"]{background:linear-gradient(160deg,transparent 0 0),#A9D3C3 !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;box-shadow:none !important;overflow:hidden !important}
[data-wk="rpcard"] *{color:#4A3A30 !important}
[data-wk="rpflap"]{height:48px !important;bottom:auto !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important}
[data-wk="rpseal"]{border:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;width:26px !important;height:26px !important;left:50% !important;margin-left:-13px !important;top:30px !important}
[data-wk="rpseal"] *{display:none !important}
[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"] > div:not([data-wk]){padding-top:60px !important;padding-left:16px !important;padding-bottom:14px !important;text-align:center !important}
[data-wk="rpcard"][data-status="done"]{background:#FBF6EA !important;filter:none !important;opacity:.85 !important}
[data-wk="rpcard"][data-status="done"] [data-wk="rpflap"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMDAgNjAnIHByZXNlcnZlQXNwZWN0UmF0aW89J25vbmUnPjxwYXRoIGQ9J00wIDAgTDUwIDU4IEwxMDAgMCcgZmlsbD0nI0YzRUJEQScgc3Ryb2tlPScjNEEzQTMwJyBzdHJva2Utd2lkdGg9JzEuNicgdmVjdG9yLWVmZmVjdD0nbm9uLXNjYWxpbmctc3Ryb2tlJy8+PC9zdmc+") center/100% 100% no-repeat !important}
/* 拆开前后那一页 */
[data-wk="rpenvelope"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScyMicgaGVpZ2h0PScyMicgdmlld0JveD0nMCAwIDIyIDIyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PGNpcmNsZSBjeD0nMTQnIGN5PScxNCcgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PC9zdmc+") 0 0/22px 22px,#A9D3C3 !important;border:1.6px solid #4A3A30 !important;border-radius:24px !important;box-shadow:0 10px 30px rgba(74,58,48,.25) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:#8FC0AE !important;border-color:#4A3A30 !important}
[data-wk="rpenvelope"] *{color:#4A3A30 !important}
[data-wk="rpenvelope"][data-stage="open"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScyMicgaGVpZ2h0PScyMicgdmlld0JveD0nMCAwIDIyIDIyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PGNpcmNsZSBjeD0nMTQnIGN5PScxNCcgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PC9zdmc+") 0 0/22px 22px,#FBF6EA !important}
[data-wk="rpopenbtn"]{background:#FBF6EA url("data:image/svg+xml;base64,") center/60% no-repeat !important;border:1.6px solid #4A3A30 !important;box-shadow:none !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpamount"]{color:#4A3A30 !important}
[data-wk="rpavatar"]{border-radius:10px !important;box-shadow:0 0 0 1.6px #4A3A30 !important}
[data-wk="rpclose"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;color:#4A3A30 !important}
/* 照片：米白边相框 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:10px !important;background:#F3EBDA !important;border:1px solid rgba(74,58,48,.2) !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#4A3A30 !important}
/* 语音：跟气泡一样，我青瓷、他米白，焦茶描边 */
[data-wk="voice"][data-me]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;box-shadow:none !important}
[data-wk="voice"][data-me="1"]{background:#A9D3C3 !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#4A3A30 !important}
[data-wk="voicewave"] span{background:#4A3A30 !important}
[data-wk="wxcardsky"]{background:#F3EBDA !important}
[data-wk="wxcardsky"] *{color:#4A3A30 !important}
[data-wk="wxcardsky"] svg{stroke:#4A3A30 !important}
[data-wk="wxcardsay"]{background:#FBF6EA !important;color:#4A3A30 !important;border-top:1.6px solid #4A3A30 !important}
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;border:none !important;width:22px !important;height:22px !important;border-radius:0 !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#4A3A30 !important}
[data-wk="namecard"] img{border-radius:10px !important;box-shadow:0 0 0 1.6px #4A3A30 !important}
/* 拍一拍、通话结束、系统提示：米白小胶囊焦茶边 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:999px !important;color:#4A3A30 !important;padding:2px 12px !important}
[data-wk="note"][data-part="call"] svg{stroke:#4A3A30 !important}
[data-wk="note"][data-part="callsum"]{color:#A79E92 !important}
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{display:inline-block !important;background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:999px !important;color:#4A3A30 !important;padding:2px 12px !important;font-style:normal !important}
[data-wk="offlogtitle"]{color:#4A3A30 !important;font-weight:700 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#6F8F82 !important}
[data-wk="offlogtranscript"]{border-top:1.6px solid #4A3A30 !important}
/* 加号面板 */
[data-wk="chatpanel"]{background:#FBF6EA !important;border-top:1.6px solid #4A3A30 !important}
[data-wk="chattoolicon"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:14px !important;box-shadow:none !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{background:#A9D3C3 !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#4A3A30 !important;color:#4A3A30 !important}
[data-wk="chattoollabel"]{color:#4A3A30 !important}
/* 引用三处 */
[data-wk="quotedraft"]{background:#FBF6EA !important;border-top:1.6px solid #4A3A30 !important}
[data-wk="quote"]{background:#FBF6EA !important;color:#4A3A30 !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;opacity:1 !important;padding-left:24px !important;background-image:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTEgMTEgVjEgSDExJyBmaWxsPSdub25lJyBzdHJva2U9JyM0QTNBMzAnIHN0cm9rZS13aWR0aD0nMS42Jy8+PC9zdmc+") !important;background-repeat:no-repeat !important;background-position:8px 6px !important;background-size:9px 9px !important}
[data-wk="quote"][data-me="1"]{background-color:#DCEDE6 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#4A3A30 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid #4A3A30 !important;padding-left:8px !important;opacity:.7 !important}


/* 按键回到 app 原来的顺序：左边是发送（纸飞机），最右是回复（青瓷「回复」字块，角上一颗星） */
[data-wk="send"]{order:0 !important;width:32px !important;min-width:32px !important;height:32px !important;border:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;margin-right:0 !important}
[data-wk="send"]::before,[data-wk="send"]::after{content:none !important}
[data-wk="chatreply"]{position:relative !important;overflow:visible !important;width:64px !important;min-width:64px !important;height:36px !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;background:#A9D3C3 !important;margin-right:6px !important}
[data-wk="chatreply"]::before{content:"回复" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;font-size:14px !important;letter-spacing:.2em !important;color:#4A3A30 !important}
[data-wk="chatreply"]::after{content:"" !important;position:absolute !important;right:-9px !important;bottom:-9px !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
/* 顶栏：不再是一条平横栏——点点底延伸上来，下沿是焦茶描边的圆角，名字装进米白小胶囊，右下角趴一只小猫 */
[data-wk="chathead"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScyMicgaGVpZ2h0PScyMicgdmlld0JveD0nMCAwIDIyIDIyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PGNpcmNsZSBjeD0nMTQnIGN5PScxNCcgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PC9zdmc+") 0 0/22px 22px,#F3EBDA !important;border-bottom:none !important;border-radius:0 0 22px 22px !important;box-shadow:0 1.6px 0 #4A3A30 !important;position:relative !important;overflow:visible !important;z-index:5 !important}
[data-wk="chathead"]::after{content:none !important}
[data-wk="chathead"] [data-wk="headname"] > [data-wk="headink"]{display:inline-flex !important;background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:999px !important;padding:0 12px !important}


/* 顶栏两个人：他的头像和我的头像叠在一起，中间一颗小星；小猫趴在两颗头像顶上，尾巴垂到我这边 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-12px !important;z-index:1 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img{width:40px !important;height:40px !important;border-radius:10px !important;box-shadow:0 0 0 1.6px #4A3A30,0 0 0 3.5px #F3EBDA !important;transform:rotate(6deg) !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]) > [data-wk="avatar"],[data-wk="chathead"] button:has(> [data-wk="avatar"]) img{width:40px !important;height:40px !important;transform:rotate(-6deg) !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-12px !important;bottom:-6px !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:3 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::after{content:"" !important;position:absolute !important;left:24px !important;top:-10px !important;width:42px !important;height:17.5px !important;background:url("data:image/svg+xml;base64,") center bottom/contain no-repeat !important;z-index:4 !important;pointer-events:none !important}
